-- 5) 재발 방지 — 역마진(판매가 < 원가) 방지 CHECK 제약 (NOT VALID: 기존 미검증 행 때문에
--    마이그레이션이 막히지 않도록 하되, 이후 모든 INSERT/UPDATE에는 즉시 적용됨)
ALTER TABLE zen_ups_base_rates ADD CONSTRAINT chk_base_rates_no_reverse_margin CHECK (selling_price >= cost_price) NOT VALID;
ALTER TABLE zen_ups_weight_tier_rates ADD CONSTRAINT chk_tier_rates_no_reverse_margin CHECK (price_per_kg_selling >= price_per_kg_cost) NOT VALID;
ALTER TABLE zen_ups_freight_minimums ADD CONSTRAINT chk_freight_min_no_reverse_margin CHECK (min_charge_selling >= min_charge_cost) NOT VALID;

COMMIT;
